using System.Text.Json;
using System.Text.RegularExpressions;
using System.Xml.Linq;
namespace SoloCamera.Windows;
public static class IntegrationTest {
 public static async Task Run(string xml,string report,string obsConfig){var results=new List<string>();var doc=XDocument.Load(xml);string details=doc.Descendants("node").Select(n=>(string?)n.Attribute("text")??"").First(t=>Regex.IsMatch(t,"Key: [a-fA-F0-9]{32}"));string key=Regex.Match(details,"Key: ([a-fA-F0-9]{32})").Groups[1].Value;using var camera=new PhoneConnection();var cameras=new[]{camera,new PhoneConnection(),new PhoneConnection(),new PhoneConnection()};using var server=new LocalFeedServer(cameras);try{camera.Connect("127.0.0.1",key,48731);await File.WriteAllTextAsync(report,"Awaiting phone approval");for(int i=0;i<450&&camera.Frames<30;i++){await Task.Delay(100);if(!camera.Running)throw new Exception(camera.Status);}if(camera.Frames<30)throw new Exception("Missing phone frames: "+camera.Status);long before=camera.Frames;await Task.Delay(10000);long frames=camera.Frames-before;if(frames<50)throw new Exception("Stream stalled");results.Add($"PASS TECNO encrypted preview: {frames} frames in 10 seconds");using var http=new HttpClient();byte[] jpeg=await http.GetByteArrayAsync(server.Url.Replace("/feed","/frame/0"));await File.WriteAllBytesAsync(Path.ChangeExtension(report,"jpg"),jpeg);results.Add("PASS Live JPEG available to OBS browser source");using var config=JsonDocument.Parse(await File.ReadAllTextAsync(obsConfig));using var obs=new ObsBridge();await obs.Connect(config.RootElement.GetProperty("server_port").GetInt32(),config.RootElement.GetProperty("server_password").GetString()!);await obs.Setup(server.Url);var status=await obs.Request("GetVirtualCamStatus");if(!status.GetProperty("outputActive").GetBoolean())await obs.Request("StartVirtualCam");for(int tries=0;tries<30&&!status.GetProperty("outputActive").GetBoolean();tries++){await Task.Delay(200);status=await obs.Request("GetVirtualCamStatus");}if(!status.GetProperty("outputActive").GetBoolean())throw new Exception("Virtual camera not active");results.Add("PASS OBS Virtual Camera started");await File.WriteAllLinesAsync(report,results.Append("RUNNING webcam; capture test now"));server.Mode=0;await Task.Delay(8000);var screenshot=await obs.Request("GetSourceScreenshot",new{sourceName="Solo Camera · Program",imageFormat="png",imageWidth=640,imageHeight=360});string image=screenshot.GetProperty("imageData").GetString()!;await File.WriteAllBytesAsync(Path.ChangeExtension(report,"png"),Convert.FromBase64String(image[(image.IndexOf(',')+1)..]));await Task.Delay(45000);await obs.Request("StopVirtualCam");results.Add("PASS OBS screenshot saved; virtual camera stopped");camera.Disconnect();await camera.WaitStopped();if(camera.Latest!=null)throw new Exception("Stale frame after disconnect");results.Add("PASS Phone disconnect clears preview");}catch(Exception e){results.Add("FAIL "+e.Message);}finally{foreach(var c in cameras)c.Dispose();await File.WriteAllLinesAsync(report,results);}}
}


